CREATE TABLE warehouses(id uuid PRIMARY KEY,created_at timestamptz NOT NULL,updated_at timestamptz NOT NULL,version bigint NOT NULL,code text,name text,address text,status text,UNIQUE(code));
CREATE TABLE zones(id uuid PRIMARY KEY,created_at timestamptz NOT NULL,updated_at timestamptz NOT NULL,version bigint NOT NULL,warehouse_id uuid,code text,name text,type text,FOREIGN KEY(warehouse_id) REFERENCES warehouses(id),UNIQUE(warehouse_id,code));
CREATE TABLE racks(id uuid PRIMARY KEY,created_at timestamptz NOT NULL,updated_at timestamptz NOT NULL,version bigint NOT NULL,zone_id uuid,code text,FOREIGN KEY(zone_id) REFERENCES zones(id),UNIQUE(zone_id,code));
CREATE TABLE locations(id uuid PRIMARY KEY,created_at timestamptz NOT NULL,updated_at timestamptz NOT NULL,version bigint NOT NULL,rack_id uuid,warehouse_id uuid,code text,max_weight float8,max_volume float8,current_weight float8,current_volume float8,distance float8,storage_type text,zone_type text,status text,occupancy_revision bigint,FOREIGN KEY(rack_id) REFERENCES racks(id),FOREIGN KEY(warehouse_id) REFERENCES warehouses(id),UNIQUE(warehouse_id,code),CHECK(max_weight>0 AND max_volume>0 AND current_weight>=0 AND current_volume>=0));
